import java.util.*;

class Solution {
    public List<List<String>> mirrorCuts(String s) {
        int n = s.length();
        boolean[][] pal = new boolean[n][n];
        for (int i = n - 1; i >= 0; i--)            // fill so pal[i+1][j-1] is ready
            for (int j = i; j < n; j++)
                pal[i][j] = s.charAt(i) == s.charAt(j) && (j - i < 2 || pal[i + 1][j - 1]);
        List<List<String>> out = new ArrayList<>();
        go(s, 0, pal, new ArrayList<String>(), out);
        return out;
    }

    private void go(String s, int start, boolean[][] pal, List<String> cur, List<List<String>> out) {
        if (start == s.length()) { out.add(new ArrayList<>(cur)); return; }
        for (int end = start; end < s.length(); end++) {
            if (!pal[start][end]) continue;         // piece must be a palindrome
            cur.add(s.substring(start, end + 1));
            go(s, end + 1, pal, cur, out);
            cur.remove(cur.size() - 1);
        }
    }
}

