class Solution:
    def mirrorCuts(self, s: str) -> List[List[str]]:
        out, cur = [], []
        def go(i):
            if i == len(s): out.append(cur[:]); return
            for j in range(i + 1, len(s) + 1):
                p = s[i:j]
                if p == p[::-1]:
                    cur.append(p); go(j); cur.pop()
        go(0)
        return out

