function mirrorCuts(s) {
  const memo = new Map();
  function from(i) {
    if (i === s.length) return [[]];
    if (memo.has(i)) return memo.get(i);
    const res = [];
    for (let j = i + 1; j <= s.length; j++) {
      const p = s.slice(i, j);
      if (p === [...p].reverse().join("")) for (const rest of from(j)) res.push([p, ...rest]);
    }
    memo.set(i, res); return res;
  }
  return from(0);
}
